/**
 * @summary Generate a downloadable report
 */
export const generateReportBodyFormatDefault = `pdf`;
export const generateReportBodyIncludeChartsDefault = true;

export const GenerateReportBody = zod.object({
  "type": zod.enum(['energy', 'faults', 'runtime', 'voltage_quality', 'maintenance', 'learning', 'comprehensive']),
  "from": zod.coerce.date(),
  "to": zod.coerce.date(),
  "format": zod.enum(['pdf', 'csv', 'excel', 'json']).default(generateReportBodyFormatDefault),
  "includeCharts": zod.boolean().default(generateReportBodyIncludeChartsDefault)
})

export const GenerateReportResponse = zod.object({
  "reportId": zod.string(),
  "status": zod.enum(['generating', 'ready', 'error']),
  "downloadUrl": zod.string().nullable(),
  "message": zod.string().nullish()
})


